 '<h2 style="font-family:\'Onest\',sans-serif;font-size:27px;font-weight:800;letter-spacing:-.7px;color:#03235F;margin:30px 0 6px">Популярные подборки</h2>'
 '<p style="font-size:15px;color:#3A4C6D;margin:0 0 16px">Готовые ответы под частые задачи и локации — с рекомендациями и переходом в калькулятор.</p>'
 '<div style="font-size:13px;font-weight:700;color:#8290A8;letter-spacing:.3px;margin:0 0 9px">ПО СТРАНАМ</div>'
 '<div style="display:flex;flex-wrap:wrap;gap:9px;margin:0 0 18px">'+chips(geos)+'</div>'
